<div class="page-header"><div><h1><?= e($teacher['first_name'].' '.$teacher['last_name']) ?></h1><div class="subtitle"><?= e($teacher['employee_no']) ?> · <?= e($teacher['department_name']??'No department') ?></div></div><div><?= Button::outline('Edit',href:'/teachers/'.$teacher['id'].'/edit') ?></div></div>
